// Üretilen dosya: tool/ozgun/uret.py. İstatistik ve Veri Bilimi · Olasılık dağılımları: binom, normal, Poisson (zor).
const ozStatistics8Zor = <(String, String, List<String>, String)>[
  ('Başarı olasılığı sabit olan 10 bağımsız denemede toplam 3 başarı gerçekleştiği biliniyor. Bu bilgiyle onuncu (son) denemenin başarı olma olasılığı kaçtır?', '0,3', ['0,5', 'p\'ye bağlıdır', '0,03'], 'Toplam 3 başarı bilindiğinde başarıların 10 denemeye yerleşimi eşit olasılıklıdır; herhangi bir denemenin başarı olma olasılığı 3/10\'dur ve p\'den bağımsızdır.'),
  ('Bir ankette 10 kişiye üç seçenekten biri soruluyor; seçeneklerin tercih olasılıkları 0,2, 0,3 ve 0,5\'tir ve yanıtlar bağımsızdır. Birinci ve ikinci seçeneği tercih edenlerin sayıları arasındaki kovaryans kaçtır?', '−0,6', ['0', '0,6', '−0,06'], 'Multinom dağılımında Cov(Xᵢ, Xⱼ) = −n·pᵢ·pⱼ = −10 · 0,2 · 0,3 = −0,6\'dır; toplam sabit olduğu için ilişki negatiftir.'),
  ('Başarı olasılıkları 0,95, 0,90 ve 0,80 olan üç bağımsız denemedeki başarı sayısının (Poisson-binom dağılımı) beklenen değeri ve varyansı nedir?', '2,65 ve yaklaşık 0,30', ['2,65 ve yaklaşık 0,26', '2,70 ve yaklaşık 0,30', '0,88 ve yaklaşık 0,10'], 'Beklenen değer Σpᵢ = 2,65; varyans Σpᵢ(1 − pᵢ) = 0,0475 + 0,09 + 0,16 ≈ 0,30\'dur. Aynı ortalamalı Binom(3; 0,883) varyansı ≈ 0,31 olup biraz daha büyüktür.'),
  ('λ = 0,1 olan bir Poisson değişkeni için P(X ≥ 2) olasılığının iyi bir yaklaşık değeri hangisidir?', 'λ²/2 ≈ 0,005', ['λ ≈ 0,1', 'λ/2 ≈ 0,05', 'e^(−λ) ≈ 0,905'], 'Küçük λ için en büyük terim P(X = 2) = e^(−λ)λ²/2 ≈ λ²/2\'dir; kesin değer ≈ 0,0047\'dir.'),
  ('Her biri 0,5 olasılıkla kız ya da erkek doğan 4 çocuklu bir ailede çocukların ikisinin kız ikisinin erkek olma olasılığı, 3–1 dağılımının (hangi cinsiyet çoğunlukta olursa olsun) olasılığıyla karşılaştırıldığında hangisi doğrudur?', '3–1 dağılımı daha olasıdır', ['2–2 dağılımı daha olasıdır', 'İkisi eşit olasılıklıdır', '4–0 dağılımı ikisinden de olasıdır'], 'P(2–2) = 6/16 = 3/8, P(3–1 ya da 1–3) = 8/16 = 1/2\'dir. Sezgiye aykırı olarak dengesiz 3–1 dağılımı daha olasıdır.'),
  ('Bir değişkenin ortalaması 5, varyansı 6 olarak verilmiştir. Bu değişkenin binom dağılımına uyması hakkında ne söylenebilir?', 'Mümkün değildir, çünkü binomda varyans ortalamadan küçüktür', ['Mümkündür; n = 6 ve p = 5/6 alınırsa dağılım binom olur', 'Yalnız p = 0,5 ise mümkündür', 'Mümkündür, çünkü varyans her değeri alabilir'], 'Binomda Var = np(1 − p) = E(X)·(1 − p) olduğundan varyans ortalamayı aşamaz; 6 > 5 olduğu için binom olamaz.'),
  ('X ~ Binom(50, p) ve Var(X) = 8 olduğu biliniyor. p hakkında ne söylenebilir?', 'p 0,2 ya da 0,8 olabilir; varyans tek başına ayırt etmez', ['p kesinlikle 0,16\'dır', 'p kesinlikle 0,2\'dir, çünkü küçük kök her zaman seçilir', 'p kesinlikle 0,8\'dir'], '50·p(1 − p) = 8 ise p(1 − p) = 0,16\'dır; bu denklemin iki kökü 0,2 ve 0,8\'dir. Ortalama bilinmeden hangisi olduğu söylenemez.'),
  ('X ~ Binom(9; 0,4) dağılımında (n + 1)p = 4 bir tam sayıdır. Bu durumda dağılımın modu için hangisi doğrudur?', '3 ve 4 eşit olasılıklı iki moddur', ['Yalnız 4 moddur, çünkü (n + 1)p değerine eşittir', 'Yalnız 3,6 moddur', 'Dağılımın modu yoktur'], '(n + 1)p tam sayı olduğunda (n + 1)p ve (n + 1)p − 1 değerleri eşit olasılıklı iki mod olur: P(X = 3) = P(X = 4) ≈ 0,251.'),
  ('Bir öğretmen 4 seçenekli 20 soruluk bir testte geçme notunu 10 doğru olarak belirliyor. Tamamen rastgele işaretleyen birinin geçme olasılığı yaklaşık kaçtır?', '0,014', ['0,250', '0,500', '0,100'], 'X ~ Binom(20; 0,25) için P(X ≥ 10) ≈ 0,014\'tür; ortalama 5 doğru olduğundan 10 doğru oldukça uç bir sonuçtur.'),
  ('Bir takımın her maçı kazanma olasılığı 0,6\'dır ve maçlar bağımsızdır. 3 maçlık bir seride en az 2 maç kazanma olasılığı ile 5 maçlık bir seride en az 3 maç kazanma olasılığı karşılaştırıldığında hangisi doğrudur?', '5 maçlık seride olasılık daha yüksektir', ['3 maçlık seride olasılık daha yüksektir', 'İki olasılık eşittir, çünkü oran aynıdır', 'İkisi de 0,6\'dır'], '3 maçta P(X ≥ 2) = 0,648, 5 maçta P(X ≥ 3) ≈ 0,683\'tür. Seri uzadıkça güçlü tarafın çoğunluğu alma şansı artar.'),
  ('r. başarının k. denemede gelme olasılığı neden C(k − 1, r − 1)·pʳ·(1 − p)ᵏ⁻ʳ biçimindedir; katsayının C(k, r) değil C(k − 1, r − 1) olmasının nedeni nedir?', 'Son deneme mutlaka başarı olmalı, yalnız ilk k − 1 deneme serbesttir', ['Denemeler birbirine bağımlıdır', 'İlk deneme her zaman başarısızdır', 'Başarıların tümü ardışık denemelerde gelmek zorundadır'], 'k. denemenin r. başarı olması gerekir; geriye kalan r − 1 başarı ilk k − 1 denemeye C(k − 1, r − 1) yolla yerleşir.'),
  ('Bir kişi bir anahtarlıktaki 5 anahtarı rastgele deniyor ve her denemeden sonra yanlış anahtarı ayırmadan karıştırıp yeniden seçiyor. Doğru anahtarı bulana kadar beklenen deneme sayısı kaçtır?', '5', ['3', '2,5', '4'], 'Anahtarlar geri konduğundan her deneme 1/5 olasılıkla başarılıdır; geometrik dağılımda beklenen değer 1/p = 5\'tir. Yanlışlar ayrılsaydı beklenen değer 3 olurdu.'),
  ('Bir ofise günde gelen kargo sayısı Poisson(10) dağılıyor. Süreklilik düzeltmeli normal yaklaşımla bir günde en çok 15 kargo gelme olasılığı yaklaşık kaçtır? (Φ(1,74) ≈ 0,959)', '0,959', ['0,943', '0,500', '0,9772'], 'μ = 10, σ = √10 ≈ 3,16\'dır. P(X ≤ 15) ≈ P(Y ≤ 15,5) = Φ(5,5/3,16) = Φ(1,74) ≈ 0,959. Kesin Poisson değeri ≈ 0,951\'dir.'),
  ('Multinom dağılımında iki farklı kategorinin sayımları X_i ve X_j arasındaki kovaryansın işareti nedir?', 'Negatif', ['Pozitif', 'Sıfır', 'p_i ile p_j\'ye göre değişir'], 'Toplam n sabit olduğundan bir kategorideki artış ötekilerde azalma gerektirir; Cov(X_i, X_j) = −n·p_i·p_j < 0\'dır.'),
  ('λ tam sayı olduğunda Poisson dağılımının modu için hangisi doğrudur?', 'λ ve λ − 1 eşit olasılıklı iki moddur', ['Yalnız λ moddur', 'Yalnız λ + 1 moddur, çünkü oran 1\'i aşar', 'Dağılımın modu yoktur'], 'P(λ)/P(λ − 1) = λ/λ = 1 olduğundan iki değer eşit ve en büyük olasılığa sahiptir.'),
  ('X ~ Poisson(5) ise Y = 2X değişkeni için hangisi doğrudur?', 'Y Poisson dağılmaz, çünkü varyansı ortalamasından büyüktür', ['Y ~ Poisson(10) olur, çünkü ortalama iki katına çıkar', 'Y ~ Poisson(5) olur', 'Y ~ Poisson(2,5) olur'], 'E(Y) = 10 ama Var(Y) = 4 · 5 = 20\'dir; ayrıca Y yalnız çift değer alır. Poisson\'da ortalama ile varyans eşit olmalıdır.'),
  ('Bir kavşaktan geçen araçlar Poisson(λ) dağılıyor; her araç bağımsız olarak p olasılıkla otomobil, 1 − p olasılıkla başka bir araçtır. Otomobil sayısı ile diğer araç sayısı arasındaki ilişki nedir?', 'Birbirinden bağımsız iki Poisson değişkenidir', ['Negatif ilişkili iki binom değişkenidir', 'Toplamları sabit olduğundan birbirine bağımlıdır', 'Pozitif ilişkili, ortak varyanslı iki normal değişkendir'], 'Poisson inceltmesinde ayrılan iki akım Poisson(λp) ve Poisson(λ(1 − p)) olur ve şaşırtıcı biçimde birbirinden bağımsızdır.'),
  ('Poisson yaklaşımında binomun varyansı np(1 − p) yerine np alınır. Bu yaklaşım hatasının küçük kalması neden p\'nin küçük olmasına bağlıdır?', '1 − p çarpanı 1\'e yakın olduğunda iki varyans neredeyse eşitlenir', ['p küçükken n de küçülür', 'p küçükken ortalama sıfır olur', 'Poisson\'un varyansı p\'den bağımsız olduğu için hata hep sıfırdır'], 'np(1 − p) ile np arasındaki oran 1 − p\'dir; p sıfıra yakınsa bu oran 1\'e yaklaşır ve iki dağılım benzer yayılım gösterir.'),
  ('Bir ormanda alan karelerine düşen ağaç sayılarının varyansının ortalamasından çok küçük çıktığı (yayılım indeksi < 1) görülüyor. Bu durum ağaçların dağılımı hakkında ne düşündürür?', 'Ağaçlar rastgeleden daha düzenli, eşit aralıklı yayılmıştır', ['Ağaçlar kümeler hâlinde toplanmıştır', 'Ağaçlar tamamen rastgele, birbirinden bağımsız dağılmıştır', 'Veride hiç ağaç yoktur'], 'Eksik yayılım (varyans < ortalama) düzenli aralıkları, aşırı yayılım (varyans > ortalama) kümelenmeyi, indeksin 1 olması ise Poisson tipi rastgeleliği gösterir.'),
  ('Normal dağılan bir veride 1,5 × IQR kuralına göre aykırı değer sayılan gözlemlerin oranı yaklaşık kaçtır?', '%0,7', ['%5', '%0,07', '%2,5'], 'Üst sınır Q3 + 1,5·IQR ≈ μ + 2,698σ\'dır; iki kuyruktaki toplam alan ≈ 0,007 yani %0,7\'dir.'),
  ('Normal dağılan bir değişkende değerlerin yaklaşık %15,87\'si 40\'ın altında, %2,28\'i 70\'in üstündedir. Φ(1) ≈ 0,8413 ve Φ(2) ≈ 0,9772 olduğuna göre ortalama ve standart sapma nedir?', 'μ = 50, σ = 10', ['μ = 55, σ = 15', 'μ = 52,5, σ = 7,5', 'μ = 45, σ = 10'], '40 değeri z = −1\'e, 70 değeri z = 2\'ye karşılık gelir: μ − σ = 40 ve μ + 2σ = 70 denklemlerinden σ = 10, μ = 50 bulunur.'),
  ('Bir bölgede aylık yağış miktarı ortalaması 5 cm, standart sapması 4 cm olan normal dağılımla modelleniyor. Φ(1,25) ≈ 0,8944 olduğuna göre bu modelin en önemli zayıflığı nedir?', 'Ayların yaklaşık %10,6\'sı için negatif yağış öngörür', ['Yağışın ortalamasını yanlış hesaplar', 'Yağış miktarının asla 5 cm\'yi aşamayacağını öngörür', 'Standart sapma sıfır olur'], 'P(X < 0) = Φ(−1,25) ≈ 0,106\'dır; negatif olamayan bir nicelik için bu oran modelin uygun olmadığını gösterir.'),
  ('Altı Sigma yaklaşımında hedef \'milyonda 3,4 kusur\' olarak verilir; oysa ±6σ dışında kalan oran milyarda yaklaşık 2\'dir. Bu farkın nedeni nedir?', 'Süreç ortalamasının uzun vadede 1,5σ kayabileceği varsayılır', ['Altı Sigma hesabında standart sapma her zaman iki katına alınır', 'Hesapta normal yerine Poisson kullanılır', 'Kusurlar yalnız alt sınırda sayılır'], 'Ortalamanın 1,5σ kayması varsayılınca en yakın sınır 4,5σ uzaklıkta kalır; P(Z > 4,5) ≈ 3,4 × 10⁻⁶\'dır.'),
  ('Normal dağılımlı bir süreçte ortalamadan 4 standart sapmadan fazla uzaklaşan değerlerin olasılığı yaklaşık kaçtır?', 'Yaklaşık 16 000\'de 1', ['Yaklaşık 100\'de 1', 'Yaklaşık 370\'te 1', 'Yaklaşık 1 milyar gözlemde 2'], 'İki kuyruklu P(|Z| > 4) ≈ 6,3 × 10⁻⁵\'tir; bu yaklaşık 16 000 gözlemde 1\'e karşılık gelir. 370\'te 1 değeri 3σ içindir.'),
  ('Bir verinin normal Q-Q grafiğinde noktalar ortada doğruyu izliyor, iki uçta ise doğrudan uzaklaşarak \'S\' biçimini alıyor; sol uçtaki noktalar doğrunun altına, sağ uçtakiler üstüne kaçıyor. Bu durum neyi gösterir?', 'Kuyrukların normalden kalın olduğunu', ['Verinin tam olarak normal dağıldığını', 'Kuyrukların normalden ince olduğunu', 'Verinin sola çarpık olduğunu'], 'Uç değerler normalin öngördüğünden daha uçta yer alıyorsa grafiğin uçları doğrudan dışarı doğru sapar; bu kalın kuyruk göstergesidir.'),
  ('Z standart normal ise P(Z² < 3,84) olasılığı yaklaşık kaçtır?', '0,95', ['0,975', '0,84', '0,50'], 'Z² < 3,84 ifadesi |Z| < √3,84 = 1,96 demektir; bu olasılık ≈ 0,95\'tir.'),
  ('Birçok bağımsız pozitif çarpanın çarpımı olarak oluşan büyüklükler (örneğin bileşik büyüme) neden yaklaşık log-normal dağılır?', 'Logaritmaları birçok terimin toplamı olduğundan normale yaklaşır', ['Çarpım her zaman sıfıra yakınsar', 'Çarpanların her biri Poisson dağılır', 'Çarpım negatif değerler de alabilen simetrik bir dağılım oluşturur'], 'ln(X₁·X₂·…) = ln X₁ + ln X₂ + … olur; bu toplam merkezî limit etkisiyle normale yaklaştığından çarpım log-normal dağılır.'),
  ('Bir Poisson sürecinde [0, t] aralığında en az 2 olay gerçekleşmesi, hangi bekleme süresi olayıyla eşdeğerdir?', 'İkinci olayın t anına kadar gerçekleşmesi', ['İlk olayın t anından sonra gelmesi', 'İki olay arasındaki sürenin t değerini aşması', 'İkinci olayın tam t anında gelmesi'], 'N(t) ≥ 2 ancak ve ancak ikinci olayın zamanı T₂ ≤ t ise sağlanır; sayım ile bekleme süreleri bu biçimde birbirine bağlıdır.'),
  ('Ortalama ömürleri 100 saat ve 200 saat olan, birbirinden bağımsız ve üstel dağılımlı iki ampul aynı anda yakılıyor. İlk sönmeye kadar geçen sürenin beklenen değeri yaklaşık kaç saattir?', '66,7', ['150,0', '100,0', '50'], 'İki bağımsız üstelin en küçüğü oranı λ₁ + λ₂ = 0,01 + 0,005 = 0,015 olan üsteldir; ortalaması 1/0,015 ≈ 66,7 saattir.'),
  ('Bir telefon hattına bir saat içinde tam bir çağrı geldiği biliniyor; çağrılar Poisson sürecine uyuyor. Bu çağrının saatin ilk 15 dakikasında gelmiş olma olasılığı kaçtır?', '1/4', ['1/2', 'e^(−0,25)', '1 − e^(−1)'], 'Poisson sürecinde [0, t] aralığında tek olay olduğu bilinince olayın zamanı bu aralıkta düzgün dağılır; 15/60 = 1/4\'tür.'),
  ('Bir Poisson sürecinde bir saatte 6 olay gerçekleştiği biliniyor. Bu olaylardan tam 2\'sinin ilk 20 dakikada gerçekleşmiş olma olasılığı yaklaşık kaçtır?', '0,329', ['0,333', '0,250', '0,0821'], 'Koşullu olarak her olay ilk 20 dakikaya bağımsız biçimde 1/3 olasılıkla düşer: Binom(6; 1/3) için P(2) = 15 · (1/9) · (16/81) ≈ 0,329.'),
  ('Üstel dağılımın tehlike (arıza) oranı fonksiyonu için hangisi doğrudur?', 'Zamandan bağımsız, sabit bir değerdir', ['Zamanla doğrusal olarak artar', 'Zamanla üstel olarak azalır ve sıfıra yaklaşır', 'Başlangıçta sıfırdır'], 'Üstel dağılımda tehlike oranı f(t)/S(t) = λ\'dır; sabit tehlike, belleksizlik özelliğinin bir başka ifadesidir. Yıpranan parçalar için artan tehlike oranlı modeller gerekir.'),
  ('Bir sayaç saniyede ortalama 1 parçacık kaydediyor (Poisson süreci). İlk saniyede tam bir parçacık kaydedildiği bilindiğinde, ilk iki saniyede toplam tam 2 parçacık kaydedilmiş olma olasılığı yaklaşık kaçtır?', '0,368', ['0,271', '0,1839', '0,5'], 'Bağımsız artışlar nedeniyle istenen olasılık, ikinci saniyede tam bir parçacık gelme olasılığıdır: e^(−1) · 1 ≈ 0,368.'),
  ('Bir sigorta şirketi bir yılda gelen hasar başvurularının sayısını ve her başvurunun tutarını ayrı ayrı modelliyor. Başvuru sayısı ve hasar tutarı için sırasıyla en uygun dağılım türleri hangileridir?', 'Kesikli bir sayım dağılımı (Poisson gibi) ve sağa çarpık sürekli bir dağılım', ['Normal ve binom', 'Bernoulli ve Poisson', 'Sürekli düzgün dağılım ve sabit sayıda denemeye dayanan geometrik dağılım'], 'Başvuru sayısı bir sayımdır (Poisson ya da negatif binom); tutarlar ise pozitif, sürekli ve genellikle sağa çarpıktır (log-normal, gamma gibi).'),
  ('U, [0, 1] aralığında düzgün dağılan bir sayı ise X = −ln(U)/λ değişkeni hangi dağılıma uyar?', 'Oranı λ olan üstel dağılım', ['Ortalaması λ olan Poisson dağılımı', 'Ortalaması 0 olan normal dağılım', '[0, λ] aralığında düzgün dağılım'], 'Ters dönüşüm yöntemine göre F⁻¹(U) istenen dağılımı verir; üstel için F⁻¹(u) = −ln(1 − u)/λ olup 1 − U de düzgün dağıldığından −ln(U)/λ üsteldir.'),
  ('Bağımsız iki Poisson değişkeninin toplamının yine Poisson olduğunu moment üreten fonksiyonlarla göstermek için hangi özellik kullanılır?', 'Bağımsız toplamın MÜF\'ü, MÜF\'lerin çarpımıdır', ['MÜF\'ler her zaman 1\'e eşittir', 'Toplamın MÜF\'ü, MÜF\'lerin toplamına eşittir', 'MÜF yalnız sürekli dağılımlar için tanımlıdır'], 'e^(λ₁(eᵗ − 1)) · e^(λ₂(eᵗ − 1)) = e^((λ₁ + λ₂)(eᵗ − 1)) bir Poisson(λ₁ + λ₂) MÜF\'üdür; MÜF dağılımı tek türlü belirlediği için sonuç çıkar.'),
  ('Bir sayım değişkeninin olasılık üreten fonksiyonu G(s) = E(sˣ) ile veriliyor. G(0) neye eşittir?', 'P(X = 0)', ['E(X)', '1', 'P(X = 1) + P(X = 0)'], 'G(0) = Σ P(X = k)·0ᵏ toplamında yalnız k = 0 terimi kalır (0⁰ = 1); dolayısıyla G(0) = P(X = 0)\'dır.'),
  ('Poisson(λ) dağılımının olasılık üreten fonksiyonu e^(λ(s − 1)) ise s = 1 noktasındaki türevi kaçtır?', 'λ', ['1', 'e^(−λ)', 'λ²'], 'G′(s) = λe^(λ(s − 1)) olup G′(1) = λ\'dır; olasılık üreten fonksiyonun 1\'deki türevi beklenen değeri verir.'),
  ('Bir kalite mühendisi kabul örneklemesinde örneklem büyüklüğünü artırıp kabul sınırını orantılı biçimde koruyor. OC eğrisinin biçimi nasıl değişir?', 'Daha dik olur; iyi ve kötü partileri daha iyi ayırır', ['Daha yatay olur; ayırt etme gücü azalır', 'Hiç değişmez', 'Eğri yön değiştirir ve kusur oranı arttıkça kabul olasılığı da artmaya başlar'], 'Büyük örneklemde kusur oranı daha kesin tahmin edilir; bu da kabul olasılığının kritik kusur oranı çevresinde keskin biçimde düşmesini sağlar.'),
  ('Başarı olasılığı 0,2 olan 3 bağımsız denemede başarı sayısının çift (0 ya da 2) olma olasılığı kaçtır?', '0,608', ['0,500', '0,392', '0,5120'], 'P(0) = 0,512 ve P(2) = 3 · 0,04 · 0,8 = 0,096\'dır; toplam 0,608 olur. Genel formül [1 + (1 − 2p)ⁿ]/2\'dir.'),
  ('Hilesiz bir para 2 kez atılıyor ve en az bir yazı geldiği biliniyor. Bu koşul altında yazı sayısının beklenen değeri kaçtır?', '4/3', ['1', '3/2', '2/3'], 'P(X = 1) = 1/2, P(X = 2) = 1/4, P(X ≥ 1) = 3/4\'tür. E(X | X ≥ 1) = (1 · 1/2 + 2 · 1/4)/(3/4) = 1/(3/4) = 4/3.'),
  ('Yedi maçlık bir seride 4 maç kazanan takım şampiyon oluyor. Her maçı bağımsız olarak 0,6 olasılıkla kazanan bir takımın seriyi kazanma olasılığı yaklaşık kaçtır?', '0,71', ['0,60', '0,84', '0,5248'], 'Bütün 7 maç oynanmış gibi düşünülebilir: Binom(7; 0,6) için P(X ≥ 4) ≈ 0,710\'dur. Uzun seri, güçlü takımın avantajını büyütür.'),
  ('Bağımsız X ~ Binom(10; 0,3) ve Y ~ Binom(10; 0,7) için X + Y değişkeni hakkında hangisi doğrudur?', 'Binom dağılmaz, çünkü başarı olasılıkları farklıdır', ['Binom(20; 0,5) dağılır, çünkü ortalamalar toplanınca 10 olur', 'Binom(20; 1) dağılır', 'Poisson(10) dağılır'], 'Bağımsız binomların toplamı ancak p\'ler eşitse binomdur. Burada ortalama 10 olsa da varyans 2,1 + 2,1 = 4,2 olup Binom(20; 0,5)\'in varyansı olan 5\'ten farklıdır.'),
  ('Bir hastanede günlük doğum sayısı Poisson(100) dağılıyor. Normal yaklaşıma göre bir günde tam 100 doğum olma olasılığı, yoğunluğun tepe değeri 1/√(2πλ) ile yaklaşık kaçtır?', '0,040', ['0,100', '0,010', '0,3989'], 'Normal yaklaşımda P(X = 100) ≈ φ(0)/σ = 1/√(2π · 100) ≈ 0,040\'tır; kesin Poisson değeri de ≈ 0,0399\'dur. En olası değerin olasılığı bile küçüktür.'),
  ('Bir deneyde tedavi grubunun ortalaması kontrol grubununkinden 1 standart sapma yüksektir ve iki grup da aynı standart sapmalı normal dağılıyor. Tedavi grubundakilerin yüzde kaçı kontrol grubunun ortalamasını aşar? (Φ(1) ≈ 0,8413)', '%84', ['%50', '%68', '%16'], 'Kontrol ortalaması tedavi grubunda z = −1\'e karşılık gelir; P(Z > −1) = Φ(1) ≈ 0,84\'tür. Bu oran Cohen\'in U3 ölçüsü olarak bilinir.'),
  ('Bir zekâ testinde puanlar N(100; σ = 15) dağılıyor ve 145 üstü \'çok üstün\' sayılıyor. Bir alt grubun ortalaması yalnız 5 puan daha yüksek (105) ise bu gruptaki \'çok üstün\' oranı genel gruptakinin yaklaşık kaç katıdır? (P(Z > 3) ≈ 0,00135, P(Z > 2,67) ≈ 0,0038)', 'Yaklaşık 2,8 katı', ['Yaklaşık 1,05 katı', 'Yaklaşık 1,33 katı', 'Yaklaşık 10 katı'], 'Oran 0,0038/0,00135 ≈ 2,8\'dir. Ortalamadaki küçük bir kayma, uç kuyruktaki oranları orantısız biçimde büyütür.'),
  ('Hilesiz bir zar 100 kez atılıyor; tek atışın ortalaması 3,5, varyansı 35/12\'dir. Toplamın yaklaşık dağılımı için ortalama ve standart sapma nedir?', '350 ve 17,1', ['350 ve 1,7', '350 ve 291,7', '3,5 ve 17,1'], 'Toplamın ortalaması 100 · 3,5 = 350, varyansı 100 · 35/12 ≈ 291,7, standart sapması ≈ 17,1\'dir; merkezî limit teoremi gereği toplam yaklaşık normal dağılır.'),
  ('Kontrol altındaki normal bir süreçte her noktanın ±2σ sınırları içinde kalma olasılığı yaklaşık 0,9545\'tir. Bağımsız 20 noktadan en az birinin bu sınırların dışına çıkma olasılığı yaklaşık kaçtır?', '0,61', ['0,05', '0,09', '0,9545'], 'Hepsinin içeride kalma olasılığı 0,9545²⁰ ≈ 0,394\'tür; tümleyeni ≈ 0,61\'dir. Bu yüzden kontrol çizelgelerinde 2σ yerine 3σ sınırları tercih edilir.'),
  ('Bortkiewicz\'in verisinde 200 kolordu-yıl gözleminde attan düşüp tepilerek ölenlerin ortalaması yıl başına 0,61\'dir. Poisson modeline göre hiç ölüm olmayan kolordu-yıl sayısı yaklaşık kaç olmalıdır?', '109', ['61', '122', '200'], 'Beklenen sayı 200 · e^(−0,61) ≈ 200 · 0,543 ≈ 109\'dur; gözlenen değer de 109 olup modelin uyumu bu yüzden ünlüdür.'),
  ('Bir sitede saatte ortalama 2 sipariş geliyor (Poisson). Birinci saatte tam 1 ve ikinci saatte de tam 1 sipariş gelme olasılığı yaklaşık kaçtır?', '0,073', ['0,147', '0,271', '0,5'], 'Örtüşmeyen aralıklar bağımsızdır: (2e^(−2))² ≈ 0,2707² ≈ 0,073. İki saatte toplam 2 sipariş olasılığı ise ≈ 0,147\'dir; çünkü 2–0 ve 0–2 dağılımlarını da içerir.'),
  ('1943\'te Luria ve Delbrück\'ün bakteri kültürlerindeki dirençli mutant sayılarını incelediği \'dalgalanma testi\'nde varyansın ortalamadan çok büyük çıkması neyi göstermiştir?', 'Mutasyonların virüse maruz kalmadan önce rastgele oluştuğunu', ['Mutasyonların virüs tarafından doğrudan oluşturulduğunu', 'Bakterilerin hiç mutasyon geçirmediğini', 'Mutant sayılarının tam olarak Poisson dağıldığını'], 'Mutasyonlar yalnız maruziyetle oluşsaydı kültür başına sayılar Poisson\'a uyardı. Erken mutasyonların büyük \'jackpot\'lar yaratması aşırı yayılıma neden oldu; bu da rastgele mutasyon görüşünü destekledi.'),
  ('λ = 0,5 olan bir Poisson dağılımı için ortalama ile medyan karşılaştırıldığında hangisi doğrudur?', 'Medyan 0\'dır; ortalamadan küçüktür', ['Medyan ve ortalama eşittir', 'Medyan 1\'dir; ortalamadan büyüktür', 'Poisson dağılımının medyanı tanımlı değildir'], 'P(X = 0) = e^(−0,5) ≈ 0,607 > 0,5 olduğundan medyan 0\'dır; ortalama 0,5\'tir. Sağa çarpık dağılımlarda medyan ortalamanın altında kalır.'),
  ('Bir acil serviste saatte gelen hasta sayısı Poisson(4) dağılıyor. Kümülatif olasılıklar P(X ≤ 6) ≈ 0,889, P(X ≤ 7) ≈ 0,949 ve P(X ≤ 8) ≈ 0,979\'dur. Saatlik talebin en az %95 olasılıkla karşılanması için kapasite en az kaç hasta olmalıdır?', '8', ['7', '6', '4'], 'P(X ≤ 7) ≈ 0,949 eşiği tam aşamaz; ilk kez 0,95\'i geçen değer P(X ≤ 8) ≈ 0,979\'dur, bu yüzden kapasite 8 olmalıdır.'),
  ('Önceki havuz testi yönteminde (10 kişilik havuz, havuz pozitifse herkes ayrıca test ediliyor, havuz pozitiflik olasılığı ≈ 0,096) kişi başına düşen beklenen test sayısı yaklaşık kaçtır?', '0,2', ['1,0', '0,1', '0,96'], 'Havuz başına beklenen test 1 + 10 · 0,096 ≈ 1,96\'dır; 10 kişiye bölünce kişi başına ≈ 0,2 test olur. Tek tek test etmeye göre yaklaşık %80 tasarruf sağlanır.'),
  ('ln X ~ N(μ, σ²) olan log-normal bir X değişkeninin medyanı nedir?', 'e^μ', ['μ', 'e^(μ + σ²/2)', 'ln μ'], 'Logaritma sıralamayı koruduğundan ln X\'in medyanı μ ise X\'in medyanı e^μ\'dür. e^(μ + σ²/2) ise ortalamadır.'),
  ('Bir mağazada bir ürünün günlük talebi Poisson(3) dağılıyor. P(X ≤ 5) ≈ 0,916 ve P(X ≤ 6) ≈ 0,966 olduğuna göre stoksuz kalma olasılığını %5\'in altında tutmak için güne en az kaç ürünle başlanmalıdır?', '6', ['5', '3', '7'], 'Stok s ise stoksuz kalma olasılığı P(X > s)\'dir. s = 5 için ≈ 0,084, s = 6 için ≈ 0,034\'tür; en küçük uygun değer 6\'dır.'),
  ('Bir sayım verisinin ortalaması 10, varyansı 4 bulunmuştur. Bu veri için aşağıdaki modellerden hangisi yayılım bakımından en uygundur?', 'Binom modeli', ['Poisson modeli', 'Negatif binom modeli', 'Geometrik model'], 'Varyans ortalamadan küçüktür (eksik yayılım). Binomda varyans np(1 − p) < np olduğundan bu durumla uyumludur; Poisson eşit, negatif binom ise büyük varyans öngörür.'),
  ('Bir öğrenci bir sınıfta öğrencilerin boylarının normal dağıldığını, bu yüzden \'boyların tam olarak ortalamaya eşit olan öğrencinin en olası öğrenci\' olduğunu söylüyor. Bu ifadedeki kavram yanılgısı nedir?', 'Sürekli dağılımda tek bir değerin olasılığı sıfırdır; yalnız yoğunluk en yüksektir', ['Normal dağılımda en yoğun nokta ortalama değildir', 'Boylar normal dağılamaz', 'Ortalama boyda hiç öğrenci bulunamaz, çünkü ortalama genellikle kesirli bir sayıdır'], 'Yoğunluk ortalamada en yüksektir; ama sürekli bir değişkende herhangi bir değerin tam olarak gerçekleşme olasılığı sıfırdır. Anlamlı olan, ortalama çevresindeki dar aralıkların daha olası olmasıdır.'),
  ('Bir Poisson değişkeni için P(X = 2) = λ²e^(−λ)/2 olasılığını en büyük yapan λ değeri kaçtır?', '2', ['1', '0,5', '4'], 'λ²e^(−λ) ifadesinin türevi λe^(−λ)(2 − λ)\'dır; sıfır yapan pozitif değer λ = 2\'dir.'),
  ('Log-normal dağılımda ortalama e^(μ + σ²/2), medyan e^μ\'dür. σ büyüdükçe ortalama ile medyan arasındaki fark nasıl değişir?', 'Ortalama medyandan giderek daha büyük olur', ['Fark sıfıra iner', 'Medyan ortalamayı geçer', 'Fark σ\'dan bağımsızdır'], 'Ortalama/medyan oranı e^(σ²/2)\'dir ve σ ile artar; sağa çarpıklık büyüdükçe uzun kuyruk ortalamayı yukarı çeker.'),
  ('İki makine 10,0 mm hedefli parça üretiyor; şartname 9,8–10,2 mm\'dir. A makinesi N(10,00; σ = 0,10), B makinesi N(10,05; σ = 0,05) dağılımlı. Şartname dışı oran açısından hangisi doğrudur?', 'B daha az şartname dışı parça üretir', ['A daha az şartname dışı parça üretir', 'İkisi eşit oranda kusurlu üretir', 'Merkezde olduğu için A her zaman daha iyidir'], 'A için sınırlar ±2σ\'dadır: dışarıda ≈ %4,6. B için üst sınır z = 3, alt sınır z = −5\'tedir: dışarıda ≈ %0,13. Küçük yayılım, küçük merkez kaymasından daha önemlidir.'),
  ('Normal yoğunluk eğrisinin μ + σ noktasındaki yüksekliği, tepe yüksekliğinin yaklaşık kaçta kaçıdır?', '0,61', ['0,68', '0,50', '0,34'], 'f(μ + σ)/f(μ) = e^(−1/2) ≈ 0,61\'dir. 0,68 ise μ ± σ arasındaki alandır, yükseklik değildir.'),
  ('Bilgisayarların ilk dönemlerinde standart normal sayı üretmek için [0, 1] aralığında düzgün dağılmış 12 bağımsız sayı toplanıp 6 çıkarılırdı. Bu yöntemde 12 sayısının seçilmesinin nedeni nedir?', 'Toplamın varyansı 12 · (1/12) = 1 olur', ['12 sayının ortalaması tam 0 olur', 'Düzgün dağılımın basıklığı 12\'dir', '12\'den fazla sayı normal dağılımı bozar'], 'Tek bir düzgün sayının varyansı 1/12\'dir; 12 tanesinin toplamının varyansı 1, ortalaması 6\'dır. 6 çıkarılınca ortalama 0, varyans 1 olan ve merkezî limit etkisiyle yaklaşık normal dağılan bir sayı elde edilir.'),
  ('Büyük λ değerli bir Poisson dağılımının yaklaşık normal olmasını merkezî limit teoremiyle nasıl açıklayabiliriz?', 'Poisson(λ), λ tane bağımsız Poisson(1) değişkeninin toplamı gibi düşünülebilir', ['Poisson dağılımı tanım gereği normaldir', 'λ büyüdükçe Poisson\'un varyansı sıfıra iner ve bütün değerler ortalamaya yığılır', 'Poisson dağılımı süreklidir'], 'Bağımsız Poisson\'ların toplamı Poisson olduğundan Poisson(λ) birçok küçük bağımsız parçanın toplamı olarak yazılabilir; merkezî limit teoremi bu toplamı normale yaklaştırır.'),
  ('7 bitlik bir kodlama, iletimde oluşan en çok 1 bitlik hatayı düzeltebiliyor. Her bit bağımsız olarak 0,01 olasılıkla bozuluyorsa bir kod sözcüğünün doğru çözülme olasılığı yaklaşık kaçtır?', '0,998', ['0,932', '0,990', '0,9321'], 'P(X ≤ 1) = 0,99⁷ + 7 · 0,01 · 0,99⁶ ≈ 0,932 + 0,066 ≈ 0,998\'dir; tek hatayı düzeltebilmek güvenilirliği büyük ölçüde artırır.'),
  ('İki değişken için \'korelasyonsuz olmak bağımsız olmak demektir\' ifadesi hangi durumda kesin olarak doğrudur?', 'İki değişken birlikte (ortak) normal dağılıyorsa', ['Her iki değişken de yalnız pozitif değerler alıyorsa', 'Değişkenlerin ortalamaları ve varyansları birbirine eşitse', 'Değişkenlerden biri Poisson dağılıyorsa'], 'Genel olarak sıfır korelasyon bağımsızlığı göstermez; ancak ortak normal dağılımda korelasyonun sıfır olması bağımsızlığa eşdeğerdir.'),
  ('Normal dağılan bir sınavda 50. yüzdelikten 60. yüzdeliğe çıkmak için gereken z artışı ile 90. yüzdelikten 99. yüzdeliğe çıkmak için gereken artış karşılaştırıldığında hangisi doğrudur?', 'Uçtaki artış çok daha büyük bir z farkı gerektirir', ['İkisi aynı z farkını gerektirir', 'Ortadaki artış daha büyük z farkı gerektirir', 'Yüzdelikler z ile doğrusal ilişkili olduğu için fark yüzdelik farkıyla orantılıdır'], '50→60 için z yaklaşık 0\'dan 0,25\'e, 90→99 için 1,28\'den 2,33\'e çıkar. Ortada değerler yoğun olduğundan küçük puan farkları büyük yüzdelik farkları yaratır.'),
  ('20 parçalık bir partide 4 kusurlu var ve geri konmadan 5 parça seçiliyor. Seçilen kusurlu sayısının varyansı sonlu anakütle düzeltmesiyle yaklaşık kaçtır?', '0,63', ['0,80', '1,00', '0,16'], 'Binom varyansı 5 · 0,2 · 0,8 = 0,8\'dir; düzeltme çarpanı (20 − 5)/(20 − 1) = 15/19 ile çarpılınca ≈ 0,63 bulunur.'),
  ('Mil çapları N(10,00 mm; σ = 0,02 mm) dağılıyor. 9,96 mm\'nin altı hurdaya (maliyet 50 TL), 10,03 mm\'nin üstü yeniden işlemeye (maliyet 10 TL) gidiyor. Φ(2) ≈ 0,9772 ve Φ(1,5) ≈ 0,9332 ise parça başına beklenen kayıp yaklaşık kaç TL\'dir?', '1,81', ['1,14', '0,67', '5,00'], 'Hurda oranı 0,0228, yeniden işleme oranı 0,0668\'dir: 0,0228 · 50 + 0,0668 · 10 ≈ 1,14 + 0,67 = 1,81 TL.'),
  ('Sağlıklılarda bir kan değeri N(100; σ = 10), hastalarda N(130; σ = 10) dağılıyor ve 120\'nin üstü \'pozitif\' sayılıyor. Testin duyarlılığı ve özgüllüğü yaklaşık nedir? (Φ(1) ≈ 0,841, Φ(2) ≈ 0,977)', 'Duyarlılık %84, özgüllük %98', ['Duyarlılık %98, özgüllük %84', 'Duyarlılık %50, özgüllük %50', 'Duyarlılık %16, özgüllük %2,3'], 'Hastalarda 120, z = −1\'dir: P(X > 120) = Φ(1) ≈ 0,84. Sağlıklılarda 120, z = 2\'dir: P(X < 120) = Φ(2) ≈ 0,98.'),
  ('Laboratuvar referans aralıkları sağlıklı kişilerin ortalaması ±1,96 standart sapma olarak belirleniyor. Sağlıklı bir kişiye birbirinden bağımsız 20 farklı test yapılırsa en az bir testin \'aralık dışı\' çıkma olasılığı yaklaşık kaçtır?', '0,64', ['0,05', '0,95', '0,36'], 'Her test için aralık dışı olma olasılığı 0,05\'tir; 1 − 0,95²⁰ ≈ 0,64 bulunur. Bu yüzden çok sayıda testte bir anormal sonuç, tek başına hastalık göstergesi sayılmamalıdır.'),
  ('Bir toplulukta yetişkinlerin yarısı erkek (boy N(176; σ = 7)), yarısı kadındır (boy N(163; σ = 6)). P(Z > 0,57) ≈ 0,284 ve P(Z > 2,83) ≈ 0,002 olduğuna göre rastgele bir yetişkinin 180 cm\'den uzun olma olasılığı yaklaşık kaçtır?', '0,143', ['0,284', '0,286', '0,002'], 'Karışım olasılığı 0,5 · 0,284 + 0,5 · 0,002 ≈ 0,143\'tür; iki grubun olasılıkları ağırlıklarıyla toplanır.'),
  ('Bir Poisson sürecinde [0, t] aralığında tam bir olay gerçekleşme olasılığı λt·e^(−λt)\'dir. Bu olasılık hangi t değerinde en büyüktür?', 't = 1/λ', ['t = λ', 't = 2/λ', 't = 0'], 'g(t) = λt·e^(−λt) fonksiyonunun türevi λe^(−λt)(1 − λt)\'dir; sıfır yapan değer t = 1/λ, yani ortalama bekleme süresidir. Bu noktada olasılık e^(−1) ≈ 0,368 olur.'),
  ('İki bağımsız standart normal değişkenden büyük olanın beklenen değeri kaçtır?', '1/√π ≈ 0,56', ['0', '1', '√2 ≈ 1,41'], 'max(Z₁, Z₂) = (Z₁ + Z₂)/2 + |Z₁ − Z₂|/2 ifadesinin beklenen değeri E|Z₁ − Z₂|/2 = (√2 · √(2/π))/2 = 1/√π\'dir.'),
  ('Pozitif tam sayı değerli bir X için E(X) = Σ P(X ≥ k) (k = 1, 2, …) eşitliği geometrik dağılıma uygulanırsa hangi sonuç elde edilir?', 'Σ (1 − p)ᵏ⁻¹ = 1/p', ['Σ pᵏ = p/(1 − p)', 'Σ (1 − p)ᵏ = (1 − p)²', 'Σ k·p = n·p'], 'Geometrikte P(X ≥ k) = (1 − p)ᵏ⁻¹\'dir; bu geometrik serinin toplamı 1/(1 − (1 − p)) = 1/p olur.'),
  ('n denemede en az r başarı olması olayı, aynı denemeler dizisinde hangi olayla özdeştir?', 'r. başarının en geç n. denemede gelmesi', ['İlk başarının r. denemede gelmesi', 'n. denemenin başarı olması', 'r. başarının tam olarak n. denemede gelmesi'], 'İlk n denemede r ya da daha fazla başarı varsa r. başarı n\'den önce ya da n\'de gerçekleşmiştir; tersi de doğrudur. Bu, binom ile negatif binom dağılımlarını birbirine bağlar.'),
  ('Binom dağılımının modu m ile beklenen değeri np arasındaki ilişki için hangisi her zaman doğrudur?', 'Aralarındaki fark 1\'den küçüktür', ['Her zaman birbirine eşittir', 'Mod her zaman beklenen değerden büyüktür', 'Fark n ile birlikte büyür'], 'Mod ⌊(n + 1)p⌋ ya da yakınındaki tam sayıdır; (n + 1)p − 1 ≤ m ≤ (n + 1)p olduğundan |m − np| < 1 sağlanır.'),
  ('Bir çağrı merkezine saatte ortalama 2 çağrı geliyor (Poisson). \'Bir saatte en az bir çağrı gelmesi\' ile \'saatin iki yarısının her birinde en az bir çağrı gelmesi\' olasılıkları karşılaştırıldığında hangisi doğrudur?', 'Birincisi yaklaşık 0,86, ikincisi yaklaşık 0,40\'tır', ['İkisi de yaklaşık 0,86\'dır', 'Birincisi yaklaşık 0,40, ikincisi ise yaklaşık 0,86\'dır', 'İkisi de yaklaşık 0,63\'tür'], 'P(N ≥ 1) = 1 − e^(−2) ≈ 0,86\'dır. Her yarım saat bağımsız ve Poisson(1) olduğundan ikinci olay (1 − e^(−1))² ≈ 0,40 olasılıklıdır; daha güçlü bir koşul olduğu için daha az olasıdır.'),
  ('Başarı olasılığı 0,2 olan 5 deneme ile başarı olasılığı 0,1 olan 10 deneme karşılaştırılıyor; ikisinde de beklenen başarı sayısı 1\'dir. \'En az bir başarı\' olasılıkları için hangisi doğrudur?', '5 denemelik durumda biraz daha büyüktür', ['10 denemelik durumda daha büyüktür, çünkü deneme sayısı fazladır', 'İkisi tam olarak eşittir', 'İkisi de 1\'dir'], '1 − 0,8⁵ ≈ 0,672, 1 − 0,9¹⁰ ≈ 0,651\'dir. Beklenen değer aynı olsa da olasılıklar farklıdır; n büyüyüp p küçüldükçe değer 1 − e^(−1) ≈ 0,632\'ye iner.'),
  ('Bir öğrenci \'binom denemelerinin sayısı arttıkça başarı sayısının değişkenliği azalır\' diyor. Bu ifade hakkında hangisi doğrudur?', 'Yanlıştır; sayının varyansı np(1 − p) artar, yalnız oranın varyansı azalır', ['Doğrudur; sayının varyansı n ile azalır', 'Doğrudur; varyans n\'den bağımsızdır', 'Yanlıştır; hem başarı sayısının hem de başarı oranının varyansı n ile birlikte artar'], 'Var(X) = np(1 − p) n ile büyürken Var(X/n) = p(1 − p)/n küçülür. Sayıların mutlak dalgalanması artar, oranlar ise kararlı hâle gelir.'),
  ('Bir şirkette maaşlar N(5000 TL; σ = 500 TL) dağılıyor. Herkese %10 zam yapılırsa 6000 TL\'nin üstünde maaş alanların oranı yaklaşık kaç olur? (P(Z > 0,91) ≈ 0,18)', '%18', ['%2,3', '%50', '%9,1'], 'Yeni maaşlar N(5500; 550) dağılır; 6000\'in z değeri 500/550 ≈ 0,91\'dir ve P(Z > 0,91) ≈ 0,18\'dir. Yüzde zam hem ortalamayı hem standart sapmayı %10 büyütür.'),
  ('Bir fabrikada günlük iş kazası sayısı Poisson(0,2) dağılıyor ve günler bağımsız. 30 günlük bir ayda en az bir kaza olan gün sayısının beklenen değeri yaklaşık kaçtır?', '5,4', ['6,0', '0,2', '24,6'], 'Bir günde en az bir kaza olasılığı 1 − e^(−0,2) ≈ 0,181\'dir; kazalı gün sayısı Binom(30; 0,181) olup beklenen değeri ≈ 5,4\'tür. Toplam kaza beklentisi ise 6\'dır.'),
  ('Bir ölçüm yöntemiyle aynı numune iki kez bağımsız olarak ölçülüyor; her ölçümün hatası N(0; σ²) dağılıyor. İki ölçüm arasındaki farkın %95 olasılıkla aşmayacağı sınır (tekrarlanabilirlik sınırı) yaklaşık kaç σ\'dır?', '2,8σ', ['1,96σ', '2σ', '3,9σ'], 'Fark N(0; 2σ²) dağılır; standart sapması √2·σ\'dır. %95 sınırı 1,96 · √2 · σ ≈ 2,8σ olur.'),
  ('Serbestlik derecesi k olan bir t değişkeninin karesi hangi dağılıma uyar?', 'Serbestlik dereceleri 1 ve k olan F dağılımı', ['Serbestlik derecesi k olan ki-kare dağılımı', 'Standart normal dağılım', 'Serbestlik derecesi k² olan Student t dağılımı'], 't = Z/√(χ²ₖ/k) olduğundan t² = (Z²/1)/(χ²ₖ/k) olur; pay χ²(1)/1 olduğundan t² ~ F(1, k)\'dir.'),
  ('İsabet olasılığı 0,5 olan bir atıcının en az 2 isabet yapma olasılığının 0,9\'u aşması için en az kaç bağımsız atış yapması gerekir?', '7', ['4', '5', '6'], 'P(X ≥ 2) = 1 − (n + 1)/2ⁿ\'dir. n = 6 için 1 − 7/64 ≈ 0,89; n = 7 için 1 − 8/128 ≈ 0,94 olduğundan en az 7 atış gerekir.'),
  ('Ali ve Banu hilesiz birer parayı üçer kez atıyor. İkisinin elde ettiği yazı sayılarının birbirine eşit çıkma olasılığı kaçtır?', '5/16', ['1/4', '3/8', '1/2'], 'P(eşit) = Σ P(X = k)² = (1² + 3² + 3² + 1²)/64 = 20/64 = 5/16\'dır. Her olası değer için iki kişinin aynı sonucu alma olasılıkları toplanır.'),
  ('Ortalamaları 4 olan Binom(8; 0,5), Poisson(4) ve ilk başarıya kadarki deneme sayısını veren geometrik (p = 0,25) dağılımların varyansları karşılaştırıldığında en büyük varyans hangisindedir?', 'Geometrik dağılımda', ['Binom dağılımında', 'Poisson dağılımında', 'Üçünde de eşittir'], 'Varyanslar sırasıyla 8 · 0,25 = 2, λ = 4 ve (1 − p)/p² = 0,75/0,0625 = 12\'dir. Aynı ortalama farklı yayılımlarla birlikte bulunabilir.'),
  ('Ortalamaları 5 olan Poisson(5) ve Binom(10; 0,5) dağılımlarında P(X = 0) değerleri karşılaştırıldığında hangisi doğrudur?', 'Poisson\'da daha büyüktür', ['Binomda daha büyüktür, çünkü n sınırlıdır', 'İkisi eşittir', 'İkisi de sıfırdır'], 'e^(−5) ≈ 0,0067, 0,5¹⁰ ≈ 0,001\'dir. Poisson\'un varyansı (5) binomunkinden (2,5) büyük olduğundan uç değerlere daha çok olasılık verir.'),
  ('Ortalamaları 2 olan Poisson ve negatif binom (aşırı yayılımlı) sayım modellerinde \'sıfır\' sayımın olasılığı genellikle nasıl karşılaştırılır?', 'Negatif binom daha fazla sıfır öngörür', ['Poisson daha fazla sıfır öngörür', 'İkisi her zaman aynı sıfır oranını verir', 'Negatif binom hiç sıfır öngörmez'], 'Aşırı yayılım olasılığı hem büyük değerlere hem sıfıra kaydırır; örneğin ortalaması 2 olan geometrik (r = 1) modelde P(0) = 1/3 iken Poisson(2)\'de e^(−2) ≈ 0,14\'tür.'),
  ('Ortalaması ve standart sapması aynı olan bir sürekli düzgün dağılım ile bir normal dağılım karşılaştırılıyor. Ortalamadan 2 standart sapmadan fazla uzak değerlerin olasılığı için hangisi doğrudur?', 'Düzgün dağılımda 0, normalde yaklaşık %4,6\'dır', ['İkisinde de yaklaşık %4,6\'dır', 'Düzgün dağılımda daha büyüktür, çünkü kuyrukları kalındır', 'İkisinde de sıfırdır'], 'Varyansı σ² olan düzgün dağılım μ ± √3σ ≈ μ ± 1,73σ aralığına yayılır; 2σ\'nın ötesinde hiç değer yoktur. Normalde bu oran ≈ %4,6\'dır.'),
  ('Bir kentte günlük en yüksek sıcaklık yazın N(30 °C; σ = 2,5 °C) dağılıyor ve günler bağımsız kabul ediliyor. 35 °C\'yi aşan ilk güne kadar beklenen gün sayısı yaklaşık kaçtır? (P(Z > 2) ≈ 0,0228)', '44', ['2', '23', '100'], 'Bir günün 35 °C\'yi aşma olasılığı z = 2 için ≈ 0,0228\'dir; ilk böyle güne kadarki gün sayısı geometrik dağılır ve ortalaması 1/0,0228 ≈ 44\'tür.'),
  ('Boylar normal dağılıyor ve \'kısa\' (z < −1), \'orta\' (−1 ≤ z ≤ 1), \'uzun\' (z > 1) sınıflarının olasılıkları yaklaşık 0,16, 0,68 ve 0,16\'dır. Rastgele seçilen 3 kişiden her sınıftan tam bir kişi bulunma olasılığı yaklaşık kaçtır?', '0,10', ['0,017', '0,33', '0,0174'], 'Multinom olasılığı 3! · 0,16 · 0,68 · 0,16 ≈ 6 · 0,0174 ≈ 0,10\'dur; sıralama sayısı 3! = 6 ile çarpılmalıdır.'),
  ('5 seçenekli 20 soruluk bir testte doğru yanıt +4, yanlış yanıt −1 puandır. Tamamen rastgele işaretleyen bir öğrencinin puanının standart sapması yaklaşık kaçtır?', '8,9', ['1,8', '4,0', '80'], 'Doğru sayısı X ~ Binom(20; 0,2), puan S = 4X − (20 − X) = 5X − 20\'dir. Var(S) = 25 · 20 · 0,2 · 0,8 = 80; standart sapma √80 ≈ 8,9.'),
  ('Geri koymadan yapılan çekilişlerde i. ve j. çekilişin \'başarı\' göstergeleri arasındaki kovaryans negatiftir. Bu durumun hipergeometrik dağılım için sonucu nedir?', 'Başarı sayısının varyansı aynı n ve p\'li binomdan küçük olur', ['Beklenen başarı sayısı aynı n ve p\'li binomun beklenen değerinden küçük olur', 'Başarı sayısı negatif değerler alabilir', 'Varyans binomdan büyük olur'], 'Bir başarı çekildikçe kalan başarıların oranı azalır; göstergeler negatif ilişkilidir. Varyans toplamına giren negatif kovaryanslar varyansı küçültür, ortalama ise değişmez.'),
  ('X ve Y\'nin her biri standart normal, ortak dağılımları normal ve aralarındaki korelasyon 0,5\'tir. X + Y\'nin varyansı kaçtır?', '3', ['2', '1', '2,5'], 'Var(X + Y) = 1 + 1 + 2 · 0,5 · 1 · 1 = 3\'tür. Bağımsızlık olmadığında varyanslara 2·Cov eklenir; toplam yine normal dağılır.'),
  ('Bir sınavda puanlar N(70; σ = 10) dağılıyor ve geçme notu 60\'tır. Rastgele seçilen 5 öğrenciden en az 4\'ünün geçme olasılığı yaklaşık kaçtır? (Φ(1) ≈ 0,84)', '0,82', ['0,84', '0,42', '0,9688'], 'Bir öğrencinin geçme olasılığı Φ(1) ≈ 0,84\'tür. Geçen sayısı Binom(5; 0,84) olup P(X ≥ 4) = 5 · 0,84⁴ · 0,16 + 0,84⁵ ≈ 0,40 + 0,42 = 0,82.'),
  ('Bir kafede günlük şikâyet sayısı Poisson(2) dağılıyor ve günler bağımsız. Bir haftanın (7 gün) en az 5 gününde en az bir şikâyet gelme olasılığı yaklaşık kaçtır?', '0,94', ['0,86', '0,50', '0,7'], 'Bir günde en az bir şikâyet olasılığı 1 − e^(−2) ≈ 0,865\'tir. Şikâyetli gün sayısı Binom(7; 0,865) olup P(X ≥ 5) ≈ 0,94\'tür.'),
  ('Bir otobüs firması 200 rezervasyon alıyor; her yolcu bağımsız olarak 0,9 olasılıkla geliyor. Gelen yolcuların koltuk sayısını aşma olasılığının yaklaşık %5 olması için normal yaklaşımla kaç koltuk gerekir? (σ ≈ 4,24, z₀,₉₅ ≈ 1,645)', 'Yaklaşık 187', ['180', '200', 'Yaklaşık 194'], 'Gelen sayısı yaklaşık N(180; 4,24)\'tür. 180 + 1,645 · 4,24 ≈ 187 koltuk, taşma olasılığını yaklaşık %5\'e indirir.'),
  ('Bir cihaz ortalaması 1 yıl olan üstel ömürlü ve her bozulduğunda hemen yenisiyle değiştiriliyor. 3 yıllık sürede en çok bir değişim gerekme olasılığı yaklaşık kaçtır?', '0,20', ['0,05', '0,37', '0,8009'], 'Bozulmalar Poisson süreci oluşturur; 3 yıldaki bozulma sayısı Poisson(3)\'tür. P(X ≤ 1) = e^(−3)(1 + 3) ≈ 0,20.'),
  ('Bir öğretmen 30 kişilik sınıfında hiçbir öğrencinin ortalamanın 2 standart sapma dışında puan almadığını görüp \'puanlar normal dağılmıyor olmalı\' diyor. Normal dağılımda her öğrencinin bu aralıkta kalma olasılığı ≈ 0,9545 ise bu çıkarım hakkında ne söylenebilir?', 'Zayıftır; normal dağılımda bile bu durumun olasılığı yaklaşık %25\'tir', ['Doğrudur; bu durumun olasılığı sıfırdır', 'Doğrudur; normal dağılımda en az 5 öğrencinin bu aralığın dışında kalması gerekir', 'Zayıftır; çünkü bu durumun olasılığı %95,45\'tir'], '0,9545³⁰ ≈ 0,25\'tir; dörtte bir olasılıkla gerçekleşen bir durum normallik aleyhine güçlü kanıt sayılmaz. Beklenen dışarıdaki öğrenci sayısı yalnız ≈ 1,4\'tür.'),
  ('Hilesiz bir para 10 kez atılıyor. Ardışık aynı sonuçlardan oluşan blokların (koşuların) sayısının beklenen değeri kaçtır? Örneğin YYTYY dizisinde 3 koşu vardır.', '5,5', ['5', '10', '6'], 'Koşu sayısı 1 + (sonucun değiştiği yer sayısı)\'dır. 9 komşu çiftin her biri 1/2 olasılıkla farklıdır; beklenen değer 1 + 9/2 = 5,5\'tir.'),
  ('Hilesiz bir para 10 kez atılıyor. Art arda iki yazı (YY) örüntüsünün (örtüşmelere izin verilerek) görülme sayısının beklenen değeri kaçtır?', '2,25', ['2,5', '5', '1'], '9 ardışık çiftin her biri 1/4 olasılıkla YY\'dir; göstergelerin toplamının beklenen değeri 9 · 1/4 = 2,25\'tir.'),
  ('Binom dağılımının beklenen değeri np, Σ k·C(n, k)pᵏ(1 − p)ⁿ⁻ᵏ toplamından doğrudan türetilirken hangi özdeşlik kullanılır?', 'k·C(n, k) = n·C(n − 1, k − 1)', ['C(n, k) = C(n, n − k)', 'C(n, k) = C(n − 1, k) + C(n − 1, k − 1)', 'C(n, 0) = 1'], 'Bu özdeşlikle toplamdan np çarpanı çıkar ve geriye Binom(n − 1, p)\'nin olasılıkları toplamı (= 1) kalır.'),
  ('Poisson dağılımının beklenen değeri Σ k·e^(−λ)λᵏ/k! toplamından türetilirken hangi adım sonucu λ yapar?', 'k/k! = 1/(k − 1)! sadeleştirmesiyle λ dışarı alınıp kalan toplamın 1 olması', ['Toplamın her teriminin λ\'ya eşit olması', 'e^(−λ) çarpanının toplamdaki terim sayısına eşit olması ve sadeleşmesi', 'k\'nin her zaman λ\'ya eşit olması'], 'Σ k·e^(−λ)λᵏ/k! = λ Σ e^(−λ)λᵏ⁻¹/(k − 1)! olur; ikinci toplam Poisson olasılıklarının toplamı olduğundan 1\'dir.'),
  ('Zaman çok küçük Δ adımlara bölünüyor ve her adımda λΔ olasılıkla bir olay oluyor. Δ → 0 iken ilk olaya kadarki sürenin (adım sayısı × Δ) dağılımı hangisine yaklaşır?', 'Oranı λ olan üstel dağılıma', ['Normal dağılıma', 'Poisson dağılımına', 'Aralığın uzunluğuna bağlı sürekli düzgün dağılıma'], 'Adım sayısı geometriktir; P(süre > t) = (1 − λΔ)^(t/Δ) → e^(−λt) olur. Bu, geometrik dağılımın sürekli limitinin üstel olduğunu gösterir.'),
  ('Ömürleri bağımsız ve oranı λ olan üstel dağılımlı iki özdeş parça paralel bağlı; sistem ikisi de bozulunca duruyor. Sistemin beklenen ömrü nedir?', '1,5/λ', ['2/λ', '1/λ', '1/(2λ)'], 'İlk bozulmaya kadar süre üstel(2λ), ortalama 1/(2λ); belleksizlik nedeniyle kalan parçanın beklenen ömrü 1/λ\'dır. Toplam 1/(2λ) + 1/λ = 1,5/λ.'),
  ('Başarı olasılığı p olan iki bağımsız geometrik değişkenin (ilk başarıya kadarki deneme sayıları) en küçüğü hangi dağılıma uyar?', 'Başarı olasılığı 1 − (1 − p)² olan geometrik dağılım', ['Başarı olasılığı p² olan geometrik dağılım', 'Başarı olasılığı 2p olan ve deneme sayısı 2 alınan binom dağılımı', 'Ortalaması 2/p olan Poisson dağılımı'], 'Her adımda iki dizinin en az birinde başarı olma olasılığı 1 − (1 − p)²\'dir; en küçük değer bu olasılıkla geometrik dağılır. Bu, üstellerin minimumunun kesikli karşılığıdır.'),
  ('Fizikte ısı (difüzyon) denkleminin, başlangıçta tek bir noktada toplanmış bir ısı için çözümü olan \'ısı çekirdeği\' hangi biçimdedir?', 'Varyansı zamanla doğrusal artan bir Gauss (normal) eğrisi', ['Zamanla daralan bir üstel eğri', 'Sabit yükseklikte düz bir çizgi', 'Poisson olasılıklarından oluşan ve zamanla sağa kayan bir çubuk grafik'], 'Isı çekirdeği (1/√(4πDt))·e^(−x²/(4Dt)) olup varyansı 2Dt olan normal yoğunluktur; difüzyon ile rastgele yürüyüş arasındaki bağı gösterir.'),
  ('Bir fabrikada N(10 mm; σ = 0,1 mm) dağılan parçalardan 9,8–10,2 mm aralığının dışında kalanlar ayıklanıp atılıyor. Müşteriye giden parçaların dağılımı için hangisi doğrudur?', 'Kesilmiş bir normaldir; standart sapması 0,1 mm\'den küçüktür', ['Aynı N(10; 0,1) dağılımıdır', 'Standart sapması 0,1 mm\'den büyüktür, çünkü dağılımın ortası boşaltılmıştır', 'Ortalaması 10 mm\'den büyük olur'], 'Uçlardaki değerler çıkarıldığı için kalan dağılım ±2σ\'da kesilmiş normaldir; simetrik kesildiğinden ortalama 10 mm kalır, yayılım ise azalır.'),
  ('X ~ Poisson(1) için X\'in çift sayı (0, 2, 4, …) olma olasılığı (1 + e^(−2λ))/2 formülüyle yaklaşık kaçtır?', '0,57', ['0,50', '0,37', '0,43'], '(1 + e^(−2))/2 ≈ (1 + 0,135)/2 ≈ 0,57\'dir. Sıfırın olasılığı yüksek olduğu için çift değerler tek değerlerden biraz daha olasıdır.'),
];
